--
-- Estructura de tabla para la tabla `pagina`
--

CREATE TABLE `pagina` (
  `id_pagina` int(11) NOT NULL,
  `titulo` varchar(500) NOT NULL,
  `slug` varchar(500) DEFAULT NULL,
  `fecha` date NOT NULL,
  `imagen` varchar(300) NOT NULL,
  `contenido` text NOT NULL,
  `categoria` varchar(100) NOT NULL,
  `publicado_por` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
-- Volcado de datos para la tabla `pagina`
--

INSERT INTO `pagina` (`id_pagina`, `titulo`, `slug`, `fecha`, `imagen`, `contenido`, `categoria`, `publicado_por`) VALUES
(2, 'Misión, Visión y valores institucionales', 'mision-vision-y-valores-institucionales', '2025-09-05', '1784048774_MISION,VISION-Y-VALORES.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;Misión:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"text-align: justify;\"&gt;&lt;span&gt;“Somos un hospital\r\npúblico asistencial docente de la red occidente que otorga una atención de\r\ncalidad, oportuna y segura de salud, velando por tener estándares de servicio y\r\neficiencia centrada en nuestros pacientes, su familia y el entorno comunitario.\r\nContando con procesos innovadores que apoyen la gestión que realiza nuestro\r\npersonal”.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;b&gt;Visión:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"text-align: justify;\"&gt;&lt;span&gt;\r\n\r\n&lt;/span&gt;&lt;span&gt;Ser hospital innovador con altos estándares de\r\ncalidad, infraestructurales, tecnológicos, de información y transparencia.\r\nQueremos constituirnos como un hospital referente en nuestra región y a nivel\r\nnacional.&amp;nbsp;&lt;/span&gt;&lt;i&gt;&lt;span&gt;&lt;span&gt;&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/i&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;span&gt;&lt;b&gt;Respeto:&lt;/b&gt; la\r\nrealización de las labores funcionarias las realizamos en el marco de la\r\ncordialidad, igualdad, cortesía y tolerancia, entre compañeros de trabajo y en\r\nnuestra atención de los usuarios y usuarias, en relación con la ciudadanía,\r\nreconociendo en todo momento los derechos, libertades y cualidad de las\r\npersonas.&lt;/span&gt;&lt;br&gt;&lt;span&gt;﻿&lt;/span&gt;&lt;br&gt;&lt;span&gt;&lt;b&gt;Calidad:&lt;/b&gt; Implica la\r\nbúsqueda de excelencia en el trabajo, la capacidad de entregar soluciones\r\nprácticas y operables para la institución, aplicando conocimientos y destrezas\r\npara el óptimo alcance de los resultados. Es la capacidad de orientar los\r\ncomportamientos propios y/o de otros hacia el logro o superación de los\r\nresultados esperados bajo estándares de calidad establecidos, por medio de la\r\nfijación de metas desafiantes, el mejoramiento y la mantención de altos niveles\r\nde rendimiento. Implica establecer indicadores de logro y hacer seguimiento\r\npermanente.&lt;/span&gt;&lt;br&gt;﻿&lt;br&gt;&lt;span&gt;&lt;b&gt;Transparencia:&lt;/b&gt; Es\r\ngarantizar el acceso a la información veraz, objetiva y basada en hechos. Es\r\nrespetar y cautelar la publicidad de los actos, resoluciones, procedimientos y\r\ndocumentos del establecimiento, así como las de sus fundamentos y en facilitar\r\nel acceso a esa información a cualquier persona.&lt;/span&gt;&lt;br&gt;&lt;span&gt;﻿&lt;/span&gt;&lt;br&gt;&lt;span&gt;&lt;b&gt;C&lt;/b&gt;&lt;/span&gt;&lt;span&gt;&lt;b&gt;ompromiso:&lt;/b&gt; Sentir como propios los objetivos de la institución. Apoyar e instrumentar decisiones comprometido por completo con el logro de objetivos comunes, las metas y compromisos que el establecimiento tiene.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;span&gt;&lt;b&gt;Responsabilidad:&lt;/b&gt; Es el compromiso con que las personas realizan las tareas encomendadas.\r\nSu preocupación por el cumplimiento de lo asignado está por encima de sus\r\npropios intereses, la tarea asignada está Primero, lo que lleva a desempeñar\r\nlas tareas con dedicación, cumplir con los plazos, como con la calidad\r\nrequerida, y aspirando a alcanzar el mejor resultado posible, preocupándose de\r\nlograrlo sin necesidad de recordatorios o consignas especiales.&lt;/span&gt;&lt;br&gt;&lt;b&gt;﻿&lt;br&gt;&lt;/b&gt;&lt;span&gt;&lt;b&gt;Confianza:&amp;nbsp; &lt;/b&gt;Capacidad de reconocer y\r\nconvencerse acerca de las competencias propias y del resto, para asumir\r\nresponsabilidades y llevar a cabo una tarea. Teniendo certidumbre para\r\nenfrentar situaciones exigentes, tomar decisiones y dar o recibir opiniones de\r\nforma constructiva.&lt;/span&gt;&lt;br&gt;&lt;b&gt;﻿&lt;br&gt;&lt;/b&gt;&lt;span&gt;&lt;b&gt;Empatía:&lt;/b&gt;&amp;nbsp; Es la habilidad de comprender y conectar con\r\nlos pensamientos, sentimientos y experiencias de otras personas. Dicho de otra\r\nforma, es como ponerse en los zapatos de los demás. En lo laboral es comprender\r\nlos sentimientos y emociones de los demás, mediante una conducta que manifiesta\r\na los demás que estás tomando en cuenta su perspectiva.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"\"&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" align=\"center\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(3, 'Autoridades', 'autoridades', '2025-09-05', '1784050158_EQUIPO-DIRECTIVO.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;A continuación, te presentamos al equipo directivo del Hospital San José de Melipilla.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;a href=\" /app/libs/artify/uploads/1770131180_WhatsApp Image 2026-02-03 at 09.57.05.jpeg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\" /app/libs/artify/uploads/1770131180_WhatsApp Image 2026-02-03 at 09.57.05.jpeg\" style=\"width: 908px;\" width=\"150\"&gt;&lt;/a&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;a href=\"/web_hospital/app/libs/artify/uploads/1770650752_director.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;br&gt;&lt;span&gt;El Dr. Óscar Vargas Duranti es médico Cirujano de la Universidad de\r\nValparaíso, especialista Gineco-obstetra de la Universidad de Chile, con más de\r\n30 años de experiencia en cargos de jefatura y gestión en su carrera\r\nprofesional.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;Ha sido jefe del programa adulto e\r\ninfantil en APS, de la comuna de San Antonio y médico clínico en Hospital\r\nClaudio Vicuña, Director Nacional del Servicio Médico Legal durante cuatro\r\naños,&amp;nbsp; Director del Hospital San José de\r\nMelipilla en tres periodos, uno en el año 2000 y por ADP en los años 2021 al\r\n2023, &amp;nbsp;siendo renovado su segundo\r\nperiodo 2024-2027,&amp;nbsp; dado los excelentes\r\nresultados en las evaluaciones EAR 2022,&amp;nbsp; 2023 y 2024, logrando junto a su equipo el\r\nprimer lugar tres años consecutivos. &lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;Su Hospital se\r\ndestaca por contar con el primer Sello de Innovación entregado por CENS y\r\nProsalud como institución preparada para Pilotaje, y recientemente recibió el premio ISPOR en la categoría GRD en su versión 2025, obteniendo el primer lugar de la categoría por la iniciativa \"Prótesis de Rodilla vía Cirugía Mayor Ambulatoria\".&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;Actualmente se encuentra liderando uno de los desafíos más\r\nimportantes de nuestra institución, el traslado al nuevo Hospital de Melipilla que se concretará durante el año 2026.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;&lt;b&gt;EQUIPO DIRECTIVO HSJM&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;a href=\"/app/libs/artify/uploads/1770648400_1.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1770648400_1.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"\"&gt;&lt;a href=\"/app/libs/artify/uploads/1770648414_2.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1770648414_2.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;\r\n\r\n&lt;/p&gt;', 'Pagina', 'Daniel'),
(4, 'Organigrama', 'organigrama', '2025-09-05', '1784048851_ORGANIGRAMA.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Conoce el organigrama jerárquico del Hospital San José de Melipilla y accede a la resolución vigente para conocer a las jefaturas de cada unidad.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1770661968_ORGANIGRAMA 2025_page-0001.jpg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1770661968_ORGANIGRAMA 2025_page-0001.jpg\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(6, 'Hospitalización', 'hospitalizacion', '2025-09-05', '1784048873_HOSPITALIZACIÓN.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El Hospital San José de Melipilla cuenta con &lt;b&gt;239&amp;nbsp;camas de hospitalización&lt;/b&gt;, distribuidas en los distintos servicios clínicos. El moderno edificio incorpora una moderna Unidad de Paciente Crítico que considera 18 cubículos de adultos y 12 para pediatría, sumando un total de 30 camas críticas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Cuenta con 7 modernos y funcionales pabellones quirúrgicos, construidos con la más alta tecnología en equipos y equipamiento medico, de acuerdo a las necesidades sanitarias de la población. Además, tiene 12 camillas de cirugía mayor ambulatoria y 2 salas de parto integral.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El área de hospitalización de nuestro recinto asistencial se distribuye en los siguientes servicios clínicos:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783715431_3.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783715431_3.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783715443_4.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783715443_4.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;br&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(7, 'Atención Ambulatoria', 'atencion-ambulatoria', '2025-09-05', '1784048896_ATENCIÓN-AMBULATORIA.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\" face=\"Open Sans, Arial, sans-serif\"&gt;&lt;span style=\"font-size: 14px; font-family: Helvetica;\"&gt;El Hospital San José de Melipilla cuenta con un Centro de Diagnóstico y Tratamiento (CDT), área asistencial donde se concentran todas las atenciones ambulatorias que se entregan en nuestro centro de salud.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\" face=\"Open Sans, Arial, sans-serif\"&gt;&lt;span style=\"font-size: 14px; font-family: Helvetica;\"&gt;En el CDT del hospital se realizan todas las consultas de especialidad, procedimientos y entrega de medicamentos, entre otros servicios de atención abierta que no requieren hospitalización.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\" face=\"Open Sans, Arial, sans-serif\"&gt;&lt;span style=\"font-size: 14px; font-family: Helvetica;\"&gt;El CDT del Hospital San José de Melipilla funciona de lunes a viernes de 8.00 a 17.00 horas en horario continuado y en algunos casos, según demanda asistencial extiende su horario de atenciones de especialidad.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(8, 'Especialidades Médicas', 'especialidades-medicas', '2025-09-05', '1784048913_ESPECIALIDADES-MÉDICAS.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El Hospital San José de Melipilla cuenta actualmente con más de 200 médicos especialistas, profesionales de salud que se encargan de brindar una atención oportuna y respondiendo a las necesidades de nuestra comunidad usuaria.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La cartera de servicios de especialidades médicas con las que contamos actualmente son las siguientes:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783715402_1.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783715402_1.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(9, 'Especialidades-Odontológicas', 'especialidades-odontologicas', '2025-09-05', '1784048969_ESPECIALIDADES-ODONTOLÓGICAS.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;El Servicio de Odontología de nuestro hospital está formado por un equipo de 35 funcionarios, entre odontólogos especialistas, técnicos en Odontología, enfermeras y administrativos.&amp;nbsp;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;La vía de ingreso a atención es por derivación desde los establecimientos de atención primaria de la red.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;b&gt;Ubicación:&lt;/b&gt; 2° piso del edificio de consultas.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;b&gt;Horario de atención: &lt;/b&gt;lunes a viernes de 8:00 a 17:00 hrs.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;b&gt;Teléfono de SOME: &lt;/b&gt;22 8924674.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La cartera de servicios de especialidades odontológicas con las que contamos actualmente son las siguientes:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783715415_2.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783715415_2.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(10, 'Urgencias', 'urgencias', '2025-09-05', '1784049020_URGENCIAS.jpg.jpeg', '&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;La&amp;nbsp;&lt;/span&gt;&lt;a href=\"https://www.google.com/search?q=Unidad+de+Emergencia+Hospitalaria+%28UEH%29&amp;amp;sca_esv=016f34706b28a015&amp;amp;sxsrf=ANbL-n5Di6xbZ5EQhLKrQ3zti01LHWEtGg%3A1771955811611&amp;amp;source=hp&amp;amp;ei=Y-adaeSTI-7M1sQPqtTmwAU&amp;amp;iflsig=AFdpzrgAAAAAaZ30c8dJ9Hr9CNPw6W1RSBBCdS-b1L9g&amp;amp;oq=unidad+de+emegerncia+hospita&amp;amp;gs_lp=Egdnd3Mtd2l6Ihx1bmlkYWQgZGUgZW1lZ2VybmNpYSBob3NwaXRhKgIIADIHEAAYgAQYDTIGEAAYFhgeMgYQABgWGB4yBhAAGBYYHjIGEAAYFhgeMgYQABgWGB4yBhAAGBYYHjIFEAAY7wUyBRAAGO8FMggQABiABBiiBEivwwhQo4cIWMOyCHACeACQAQCYAfcCoAHkGKoBCDIxLjUuMi4xuAEByAEA-&amp;amp;sclient=gws-wiz&amp;amp;ved=2ahUKEwi30Zep2vKSAxWsqZUCHVP8HLwQgK4QegYIAQgAEAM\"&gt;&lt;span&gt;Unidad de\r\nEmergencia del&lt;/span&gt;&lt;/a&gt;&lt;span&gt; Hospital San José de Melipilla,&amp;nbsp;es un servicio especializado,\r\nque funciona las 24 horas para brindar atención médica inmediata a pacientes\r\ncon condiciones de salud graves o que revisten riesgo vital. Estas unidades\r\ngestionan la estabilización, diagnóstico y tratamiento de urgencias,\r\nclasificando a los pacientes por gravedad (triage) y no por orden de llegada.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;font&gt;El servicio de urgencias de nuestro hospital se distribuye en:&lt;/font&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;font&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;ul&gt;&lt;li style=\"text-align: justify;\"&gt;&lt;font&gt;Urgencia Adulto&lt;/font&gt;&lt;/li&gt;&lt;li style=\"text-align: justify;\"&gt;&lt;font&gt;Urgencia Infantil&lt;/font&gt;&lt;/li&gt;&lt;li style=\"text-align: justify;\"&gt;&lt;font&gt;Urgencia Gineco-obstétrica&lt;/font&gt;&lt;/li&gt;&lt;/ul&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;font&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;font&gt;&lt;b&gt;&lt;span&gt;Sistema de Categorización ESI&lt;/span&gt;&lt;/b&gt;&lt;/font&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;font&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/font&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;La categorización ESI (Emergency Severity Index) es un\r\nsistema internacional de triage de 5 niveles utilizado en los servicios de\r\nurgencia para priorizar la atención según la gravedad del paciente. Esta\r\ncategorización se realiza antes de iniciar tu atención médica y es realizada en\r\nun área denominada “selector” donde un profesional de enfermería capacitado,\r\nrealiza el control de signos vitales, entrevista inicial y otorga la\r\nclasificación según escala.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;o:p&gt;&lt;br&gt;&lt;/o:p&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;a href=\"/app/libs/artify/uploads/1771956519_49895749_1049981215185319_8945199370303700992_n.jpg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1771956519_49895749_1049981215185319_8945199370303700992_n.jpg\" style=\"width: 1525px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;b&gt;&lt;span&gt;Atención Primaria de Salud y Atenciones de Urgencias de menor complejidad&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;b&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;Recuerda que, ante cuadros de salud o patologías de menor complejidad, es importante dar un buen uso a la red asistencial. Para descongestionar la urgencia hospitalaria y garantizar un menor tiempo de espera, puedes consultar en tu SAPU/SAR más cercano a tu domicilio:&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;SAPU Dr. Francisco Boris Soler&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;Dirección: Silva Chávez N°1650, Melipilla.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;SAPU Dr. Edelberto Elgueta&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;Dirección: Arza N°1576, Melipilla.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;SAR Arpillerista Elsa Romo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\" style=\"text-align: justify; \"&gt;&lt;span&gt;Dirección: Real Audiencia N°980, Melipilla.&lt;/span&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(11, 'Laboratorio Clínico', 'laboratorio-clinico', '2025-09-05', '1784049036_LABORATORIO-CLÍNICO.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;El Laboratorio Clínico del Hospital San José de Melipilla, Hospital de mediana complejidad, es un Servicio perteneciente a la Red Occidente, dependiente de la Subdirección de Apoyo Clínico.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Su función es apoyar en el diagnóstico y control de tratamientos de los usuarios, realizando y procesando exámenes de manera oportuna y asegurando la calidad y seguridad de la atención, a través de la trazabilidad de las prestaciones, de acuerdo con normativas vigentes, con fines preventivos, diagnósticos, de control de tratamiento y control epidemiológico. Lo anterior, en las áreas de Química clínica, Hematología, Coagulación, Microbiología, Tuberculosis, Uroanálisis, Parasitología y virología; contribuyendo así a la prevención, cuidado y recuperación de la salud de los usuarios de la red occidente.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Horario de atención:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;El laboratorio clínico funciona en horario continuado las 24 horas del día, los 7 días a la semana asegurando su disponibilidad continua para el desarrollo de sus funciones.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Contacto telefónico: 228924454&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Toma de muestras:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Lunes a jueves de 8.00 a 17.00 horas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Viernes de 8.00 a 16.00 horas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(12, 'Imagenología', 'imagenologia', '2025-09-05', '1784049057_IMAGENOLOGÍA.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;﻿&lt;/span&gt;&lt;span&gt;El Servicio de Imagenología del nuevo Hospital San José de Melipilla es una unidad de apoyo clínico esencial para la atención de salud de la provincia. Nuestra labor se centra en la obtención de imágenes diagnósticas de alta calidad, utilizando equipamiento de última generación que permite entregar informes precisos y oportunos, facilitando la toma de decisiones médicas y contribuyendo a una atención segura, eficiente y centrada en las personas.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;¿A quiénes atendemos?&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Como establecimiento de alta complejidad de la Red Occidente, nuestro servicio brinda cobertura integral a la población de las comunas de Melipilla, María Pinto, Curacaví, Alhué y San Pedro, respondiendo a las necesidades de:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Pacientes ambulatorios derivados desde consultas de especialidad del hospital.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Pacientes hospitalizados en las distintas unidades del establecimiento.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Pacientes de los Servicios de Urgencia (Adulto y Pediátrico).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;b&gt;Cartera de servicios:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Disponemos de una amplia gama de estudios diagnósticos orientados a resolver las necesidades de nuestros/as usuarios/as:&lt;/span&gt;&lt;/font&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Radiología simple: Exámenes radiográficos convencionales para apoyo diagnóstico general.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Radiología portátil: Estudios realizados directamente en unidades de hospitalización y pacientes críticos que no pueden trasladarse.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Mamografía: Exámenes orientados a la detección precoz y diagnóstico de patologías mamarias.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Ecografía: Evaluaciones por ultrasonido (abdominal, partes blandas, vascular, entre otras).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Tomografía Computada (TC): Estudios de alta resolución para el diagnóstico de patologías complejas y apoyo fundamental en situaciones de urgencia.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Canales de Atención y Horarios:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Atención ambulatoria&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Lunes a Jueves: 08:00 a 17:00 horas&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Viernes: 08:00 a 16:00 horas&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La atención de pacientes hospitalizados y de urgencia se realiza de manera continua, las 24 horas del día.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Contacto telefónico:&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;span&gt;228924702&lt;/span&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(13, 'UTM', 'utm', '2025-09-05', '1784049080_MEDICINA-TRANSFUSIONAL.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La Unidad de Medicina Transfusional del Hospital de Melipilla tiene como principal objetivo garantizar la seguridad y calidad en los procesos relacionados con la sangre y sus componentes. Nuestro trabajo se orienta a optimizar el uso de los componentes sanguíneos, velar por la adecuada indicación de las transfusiones y brindar apoyo a las distintas unidades clínicas en el manejo de pacientes que requieren terapia transfusional. &lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Asimismo, contamos con un punto de atención a donantes de sangre, cuya generosidad permite apoyar los tratamientos de nuestros pacientes.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Cartera de servicios:&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Recepción de solicitudes de transfusión.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Preparación y entrega de componentes sanguíneos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Estudios inmunohematológicos (Grupo sanguíneo, pruebas de compatibilidad, detección de anticuerpos irregulares, Test de Coombs directo e indirecto).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Apoyo en tratamiento para pacientes hemofílicos (almacenamiento y administración de liofilizados de factor VIII).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Procedimientos de sangría terapéutica, para pacientes con patologías específicas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Atención de donantes de sangre. Marketing y promoción de la donación altruista.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Horarios de Atención:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Atención Inmunohematología: continua, las 24 horas del día, los 7 días de la semana.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Atención a donantes de sangre:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Lunes, miércoles y jueves: de 9:00 a 16:00 horas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Martes y viernes: de 9:00 a 14:00 horas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;&lt;span&gt;Mecanismos de contacto:&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Teléfono directo de la unidad: 228924579&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;span&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Teléfono agendamiento de donantes de sangre:        +56931263282&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Correo de donantes de sangre:                                       hospitalmelipilladonantes@ssmso.cl&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Instagram:                                                                            @donemos.sangremelipilla&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Facebook:                                                                             Donemos Sangre Melipilla&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Correo electrónico institucional de UMT:                      umt.hmelipilla@gmail.com&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Correo Jefatura Unidad de Medicina Transfusional:    elizabeth.avalos@red.salud.gob.cl&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(14, 'Medicina Física y Rehabilitación', 'medicina-fisica-y-rehabilitacion', '2025-09-05', '1784049542_MEDICINA-FISICA-YREHABILITACION.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;Nuestra unidad de Medicina Física y Rehabilitación trabaja con un equipo multidisciplinario de profesionales, tanto en atención ambulatoria, hospitalización y urgencias, contribuyendo diariamente a la recuperación y bienestar de nuestros pacientes. Promoviendo la mejora sustancial de su calidad de vida e incorporación a su vida cotidiana posterior a su proceso de atención de salud.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;Actualmente, esta unidad está compuesta por profesionales: kinesiólogos, fonoaudiólogos y terapeutas ocupacionales quienes se desempeñan en las distintas áreas de atención.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;La unidad de Medicina Física y Rehabilitación del Hospital de Melipilla, cuenta con un moderno gimnasio que incorpora nuevos box de atención y áreas de rehabilitación, tales como: hidroterapia, rehabilitación cardiopulmonar y espacios para las actividades de la vida cotidiana. Significando un importante avance para la salud de la Provincia de Melipilla.&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;br&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;La unidad de Medicina Física y Rehabilitación se encuentra ubicada en el 1° piso del edificio de consultas ambulatorias y su horario de atención es de lunes a jueves de 8.00 a 17.00 horas y los viernes de 8.00 a 16.00 horas.&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(15, 'Nutrición y SEDILE', 'nutricion-y-sedile', '2025-09-05', '1784049576_NUTRICIÓN-Y-SEDILE.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;SERVICIO DE NUTRICIÓN:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Función:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El Servicio de Nutrición tiene como función otorgar atención nutricional integral, segura y de calidad a pacientes hospitalizados y ambulatorios, contribuyendo a la prevención, tratamiento y recuperación de las distintas condiciones de salud mediante intervenciones alimentario-nutricionales basadas en evidencia.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Dirigida su labor a:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Pacientes hospitalizados en los distintos servicios clínicos, pacientes ambulatorios derivados desde especialidades médicas, usuarios pediátricos y adultos, además de brindar apoyo técnico y asesoría en materias de alimentación y nutrición a la institución.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Cartera de servicios:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Evaluación y diagnóstico nutricional de pacientes hospitalizados y ambulatorios.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Prescripción y seguimiento dietoterapéutico.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Atención nutricional clínica en servicios de hospitalización.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Atención nutricional ambulatoria de pacientes pediátricos y adultos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Educación alimentaria y nutricional a pacientes y cuidadores.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Indicación y seguimiento de soporte nutricional enteral.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Participación en visitas clínicas y trabajo interdisciplinario.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Gestión, supervisión y control de la Unidad Central de Producción (UCP).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Planificación y supervisión de regímenes alimentarios para pacientes hospitalizados.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Supervisión de la alimentación destinada a funcionarios y jardín infantil institucional.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Control de calidad e inocuidad alimentaria.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Asesoría técnica en materias de alimentación y nutrición.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Gestión y coordinación de recursos asociados a la alimentación institucional.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Contacto telefónico: 228924184 (Secretaria Nutrición).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;SEDILE – CEFE (SERVICIO DIETÉTICO DE LECHE Y CENTRAL DE FÓRMULAS ENTERALES):&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Función:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;SEDILE-CEFE es la unidad responsable de la preparación, envasado, almacenamiento y distribución de fórmulas lácteas y fórmulas enterales, garantizando procesos seguros y estandarizados bajo estrictas normas de higiene, inocuidad y trazabilidad.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Dirigida su labor a:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Recién nacidos, pacientes pediátricos, adultos hospitalizados y pacientes críticos que requieren alimentación especializada mediante fórmulas lácteas o enterales.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Cartera de servicios:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Preparación de fórmulas lácteas para pacientes pediátricos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Preparación de fórmulas enterales para pacientes adultos y críticos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Funcionamiento de Lactario institucional, orientado a la recepción, conservación y distribución segura de leche materna.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Envasado, rotulado y almacenamiento de preparaciones.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Distribución de fórmulas a los distintos servicios clínicos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Control de calidad y trazabilidad de las preparaciones.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Supervisión del cumplimiento de normas de higiene e inocuidad alimentaria.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Apoyo al soporte nutricional especializado de pacientes con requerimientos enterales.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Contacto telefónico: 228924184 (Secretaria Nutrición).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel');
INSERT INTO `pagina` (`id_pagina`, `titulo`, `slug`, `fecha`, `imagen`, `contenido`, `categoria`, `publicado_por`) VALUES
(16, 'Farmacia Ambulatoria', 'farmacia-ambulatoria', '2025-09-05', '1784049601_ATENCION-FARMACIA.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La Farmacia Ambulatoria se encarga de dispensar los medicamentos a los pacientes que se atienden en las distintas especialidades médicas de nivel ambulatorio.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Objetivo y Función:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Nuestro principal objetivo es entregar un tratamiento seguro y oportuno a todos nuestros usuarios, brindando además orientación profesional sobre el uso adecuado de sus medicamentos. Contamos con servicios farmacéuticos especializados, tanto en el área de Farmacia como en Cuidados Paliativos, orientados a la atención directa del paciente y a la revisión clínica de sus terapias, siempre buscando nuevas formas de innovar en su atención y estrategias.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Nuestro Equipo:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El servicio está compuesto por un equipo de 4 químicos farmacéuticos y 10 técnicos que se desempeñan en farmacia, dedicados a entregar una atención integral y de calidad.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Cartera de Servicios:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Ofrecemos una amplia gama de prestaciones para asegurar la continuidad de los tratamientos:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Atención a pacientes con indicación médica ambulatoria, ya sea de forma presencial en ventanilla o por modalidad de retiro programado mediante nuestra estrategia \"Agenda tu Receta\".&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Recepción y entrega de medicamentos provenientes del Hospital San Juan de Dios y el Hospital Félix Bulnes y envío de medicamentos a los centros de salud de las comunas de Talagante, María Pinto, Curacaví, San Pedro y Alhué.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Atención espontánea o programada para pacientes en Farmacia y en el programa de Cuidados Paliativos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Preparación y adecuación de dosis para tratamientos mensuales.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Entrega de equipos de oxigenoterapia domiciliaria y dispensación de insumos para programas específicos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;•	Labores de farmacovigilancia, coordinación directa con el equipo médico, gestión de la estrategia de tratamiento anticoagulante con centros de la red de salud, y apoyo técnico en el Comité de Farmacia Institucional.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Horario de Atención:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Lunes a viernes de 8:00 a 19:00 horas. No se atiende ni feriados ni festivos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Contacto y Consultas:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Atención Telefónica: 22 892 4633 (Disponible exclusivamente de 8:00 a 9:00 horas y de 15:00 a 16:00 horas).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Correo Electrónico: farmacia.cae.hospitalmelipilla@gmail.com (Para consultas fuera del horario telefónico).&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(17, 'OIRS', 'oirs', '2025-09-05', '1784049622_OIRS.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;¿Qué es la oficina de información, reclamos y sugerencias (OIRS)?&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La oficina de información, reclamos y sugerencias (OIRS) es un espacio de participación ciudadana y una vía de comunicación con los servicios de salud, hospitales, seremis de salud o ministerio de salud, facilitando el acceso a la información sobre el funcionamiento y atención en las prestaciones de salud otorgadas en sus establecimientos.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;su finalidad es garantizar el derecho de los ciudadanos a informarse, sugerir, reclamar y/o felicitar, acerca de las diversas materias en salud, retroalimentando la gestión de las reparticiones públicas.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;¿Cuál es su misión?&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Ser un espacio eficiente de atención a las personas, que favorezca la interacción con la administración de los establecimientos de salud, que garantice su derecho a informarse, sugerir, consultar, reclamar o felicitar, para contribuir a lograr una atención oportuna, de calidad, excelencia y sin discriminación.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;¿Cómo usar la OIRS en su establecimiento?&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Las personas interesadas en recibir algún tipo de información, podrán dirigirse a las OIRS de cada establecimiento de salud y solicitar al funcionario de la OIRS, que le orienten en los temas de interés en el ámbito de la salud, ya sea a través de una explicación oral o por medio de diversos soportes como: afiches, dípticos, boletines, entre otros.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;los ciudadanos que quieran presentar reclamos, sugerencias y/o felicitaciones, deben acercarse a la oficina o mesón en la cual funciona la OIRS y solicitar registrar su requerimiento.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;una vez que se registre su requerimiento, el funcionario (a) OIRS le informará de los plazos de respuesta y le hará entrega de una copia de su requerimiento. es muy importante que guarde este documento, ya que es la garantía para exigir al establecimiento que se le entregue respuesta a su inquietud.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;¿Cómo se ingresa un requerimiento ciudadano?&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;- Presencial: en cualquier oficina OIRS del establecimiento de salud, seremis de salud o departamento de atención al usuario del minsal.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;- No presencial: a través de sistema OIRS: http://oirs.minsal.cl, el sitio del ministerio de salud www.minsal.cl o llamando al fono salud responde: 600 360 7777&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;- En los casos auge se puede realizar una solicitud a través del Fonasa, llamando al teléfono 600 360 3000, acudiendo a sus oficinas a lo largo del país o a través de la página web:  www.fonasa.cl&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;Horarios de atención:&lt;/b&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La &lt;b&gt;&lt;u&gt;OIRS Central &lt;/u&gt;&lt;/b&gt;del Hospital de Melipilla se encuentra ubicada en primer piso CDT para atender sus solicitudes y requerimientos y orientar en su visita a nuestro establecimiento.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;Los Horarios de atención son de lunes a jueves de 8:00 a 17:00 horas y viernes 8:00 a 16:00 horas.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;span&gt;Contacto telefónico: 228924342.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;b&gt;&lt;u&gt;OIRS de Urgencia: &lt;/u&gt;&lt;/b&gt;  El horario de atención es 24 horas destinadas para atender sus solicitudes y entregar orientación en su atención.&amp;nbsp;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(18, 'Sistema de Visitas', 'sistema-de-visitas', '2025-09-05', '1784050181_SISTEMA-DE-VISITAS.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;El Hospital San José de Melipilla cuenta con un sistema de visitas establecido por protocolo, en el marco de la estrategia Hospital Amigo, que busca garantizar la vinculación permanente entre los pacientes y sus familias durante el proceso de hospitalización.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;Si tienes a un familiar hospitalizado en nuestros servicios clínicos, revisa los horarios de visita por piso y unidad. Recuerda que e&lt;/span&gt;&lt;span&gt;l acceso se realiza por la entrada principal y si tienes dudas, acércate al módulo de informaciones ubicado en el hall central del 1º piso.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;Horarios de visita:&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783718055_2.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783718055_2.png\" style=\"width: 1080px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783718068_3.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783718068_3.png\" style=\"width: 1080px;\" width=\"150\"&gt;&lt;/a&gt;&lt;br&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1783718081_4.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783718081_4.png\" style=\"width: 1080px;\" width=\"150\"&gt;&lt;/a&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(19, 'Hospital Amigo', 'hospital-amigo', '2025-09-05', '1784067923_HOSPITAL-AMIGO.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La línea programática Hospital Amigo del Ministerio de Salud, desempeña un papel central en la estrategia de Satisfacción Usuaria y Trato Digno, ya que su enfoque se centra en la implementación de medidas de acogida, acompañamiento e información para las personas hospitalizadas a lo largo de su proceso de atención.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Esta valiosa iniciativa se lanzó en el año 2006 y ha alcanzado en la actualidad una cobertura del 98,9% de los hospitales públicos de alta, mediana y baja complejidad a nivel nacional, todos certificados en esta línea programática.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;La implementación de Hospital Amigo se rige por la Ley de Derechos y Deberes de las personas en relación con acciones vinculadas a su atención en salud, con especial énfasis en medidas destinadas al acompañamiento.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;Conoce las 13 medidas de la Estrategia Hospital Amigo:&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;- Liderazgo institucional&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Horario visitas para personas hospitalizadas&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Horarios de entrega de información médica&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Identificación visible para personas hospitalizadas&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Identificación institucional del funcionario /a del establecimiento&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Entrega de información a familiares en unidades de emergencia&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Alimentación asistida para personas hospitalizadas&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Incorporación de la familia o persona responsable al egreso hospitalario&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Acompañamiento significativo a personas gestantes&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Acompañamiento  de niños, niñas y adolescentes hospitalizados&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Acompañamiento diurno y nocturno a personas mayores con dependencia  y/o personas con discapacidad&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Acompañamiento espiritual a personas hospitalizadas&amp;nbsp;&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;- Acompañamiento diurno y nocturno en etapa final de vida&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;a href=\"https://hospitaldemelipilla.cl/wp-content/uploads/2025/06/NORMA-TECNICA-239-HOSPITAL-AMIGO-PARA-ESTABLECIMIENTOS-ATENCION-CERRADA-PUBLICOS-Y-PRIVADOS.pdf\" target=\"_blank\"&gt;NORMA TÉCNICA HOSPITAL AMIGO&lt;/a&gt;&lt;font color=\"#000000\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(22, 'Plan de Humanización', 'plan-de-humanizacion', '2025-10-02', '1784049650_HUMANIZACION-EN-SALUD.jpg.jpeg', '&lt;p&gt;El Hospital San José de Melipilla se encuentra trabajando en la implementación de su plan de humanización, lineamiento de trabajo que nos permitirá abordar las distintas estrategias institucionales que son claves para nuestra comunidad hospitalaria.&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;Dimensiones clave de la humanización:&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;El paciente:&lt;/b&gt; Reconocer su historia de vida, llamarlo por su nombre, mantener el pudor y aliviar su dolor emocional y físico.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;La familia:&lt;/b&gt; Integrarla en el proceso de cuidado, clave en el acompañamiento y en la toma de decisiones.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;El personal de salud:&lt;/b&gt; Brindar condiciones laborales dignas, ya que \"para cuidar a otros, primero hay que cuidar a los que cuidan\".&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;El entorno físico: &lt;/b&gt;Crear espacios más amables, silenciosos y acogedores que reduzcan el estrés y la ansiedad del paciente.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;Plan de Humanización:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;Objetivo general:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Estandarizar e implementar un plan de humanización en salud para el establecimiento.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;Objetivos específicos:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Instaurar estándares mínimos de humanización en el Hospital de Melipilla.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Facilitar la hoja de ruta para el fortalecimiento de un hospital más humanizado.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Establecer la humanización como un proceso clave de calidad y seguridad asistencial.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Avanzar en estrategias de cuidado digno en forma transversal en el establecimiento.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Colaborar con los miembros del establecimiento a reconectar con lo humano.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;a href=\"/app/libs/artify/uploads/1783719625_Hospital San José de Melipilla.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783719625_Hospital San José de Melipilla.png\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;b&gt;Comité de Humanización:&lt;/b&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Desde el año 2024 nuestro hospital cuenta con un comité técnico de humanización, organismo encargado de articular las distintas estrategias y dar cumplimiento al plan de trabajo estratégico.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;b&gt;Integrantes:&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Dra. Luz Quiroga, Subdirectora Médica&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;E.U. Romina Madrid, Supervisora Pensionado&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;E.U. Fanny González, Servicio de Medicina&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;E.U. Camila Otarola, Servicio de Cirugía&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Mt. Consuelo Moraga, Supervisora Ginecología Ambulatoria&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Leyla Valladares, Jefa OIRS&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Ignacio Landaeta, Encargado Gestión Social&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Melissa Carrasco, Profesional Gestión del Cambio&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;Grethel Durán, Jefa de Gestión de Usuarios&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;a href=\"/app/libs/artify/uploads/1783720083_Captura de pantalla 2026-07-10 174730.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1783720083_Captura de pantalla 2026-07-10 174730.png\" style=\"width: 942px;\" width=\"150\"&gt;&lt;/a&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(23, 'Ley Mila', 'ley-mila', '2025-10-02', '1784050266_LEY-MILA.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;La Ley Mila (N° 21.372), implementada por el Ministerio de Salud (MINSAL), establece el derecho de niños, niñas, adolescentes y personas gestantes a un acompañamiento significativo durante su atención de salud. Esta ley permite que estas personas, hasta los 19 años, 11 meses y 29 días en el caso de los NNA, puedan estar con un adulto significativo (padre, madre, tutor u otra persona) en momentos clave de su atención, ya sea en hospitalizaciones o prestaciones ambulatorias.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;El objetivo principal es permitir que pacientes NNA y personas gestantes no estén solos en momentos críticos de su atención médica, asegurando el apoyo emocional y la presencia de figuras significativas&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;¿Quiénes son los beneficiarios?&amp;nbsp;&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Niños, niñas y adolescentes (NNA): Desde el nacimiento y hasta los 19 años, 11 meses y 29 días.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Mujeres o personas gestantes: Durante el proceso de preparto, parto y puerperio inmediato o aborto&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;¿Cómo se resguarda el acompañamiento?&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Es un derecho y es voluntario.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Puede ser realizado por un adulto significativo con asentimiento del NNA o consentimiento de la persona gestante.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	El acompañamiento será en los horarios establecidos por cada servicio clínico.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Implica respetar las instrucciones del equipo para resguardar la salud del paciente, como uso de mascarillas, lavado de manos, circulación por áreas determinadas y autorizadas por el establecimiento de salud, etc.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Implica respetar y facilitar las rutinas de trabajo del equipo (baño, entrega de turno, control de signos vitales, administración de medicamentos, etc.), incluyendo la posibilidad de tener que retirarse durante procedimientos invasivos.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Implica colaborar en el cuidado y atención del paciente, según las indicaciones del equipo.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Según lo establecido en la Ley N°20.584, el acompañante deberá cuidar las instalaciones y equipamiento del establecimiento de salud.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;¿Cuándo se podrá restringir el acompañamiento?&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Cuando el paciente solicite privacidad o no brinde su asentimiento o consentimiento.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	El equipo de salud requiera tratar un tema confidencial.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	El o la acompañante ponga en riesgo la integridad del paciente.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	El o la acompañante se encuentra sintomático o diagnosticado de alguna infección que pone en riesgo la salud del paciente.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Existe algún antecedente legal que no permita la cercanía al paciente.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Durante el acompañamiento no se permite:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Ingerir alimentos dentro de la sala.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Usar los baños de pacientes o de funcionarios.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Recostarse en la cama del paciente ni en el suelo. Bajar las barandas cuando el niño o niña se encuentre sin supervisión.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Desconectar vías, monitores u otros elementos, sin previa autorización del equipo de salud.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Sacar fotos y/o grabar videos durante procedimientos u otros procesos a funcionarios/as, sin su autorización expresa.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;o	Sacar fotos y/o grabar videos que involucren a otros pacientes, sin su asentimiento/consentimiento.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;En nuestro Hospital:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Servicio De La Mujer y Recién nacido: Gestantes y puérperas hasta los 19 años, 11 meses y 29 días De lunes a domingo con acompañamiento 24 horas u horario extendido de 09:00 a 19:00 hrs en caso que acompañante no quiera/pueda quedarse durante la noche.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Preparto – Parto: De lunes a domingo / Acompañamiento 24 horas a todas las pacientes (continuo).&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Neonatología De Lunes a Domingo, acompañamiento continuo las 24 horas.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Pediatría Hospitalizado: De Lunes a Domingo con acompañamiento continuo todos los pacientes / Tutores autorizados.&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;•	Hospitalizados (Todos los servicios): De lunes a domingo / Acompañamiento 24 horas a todas las pacientes (continuo).&amp;nbsp;&lt;/p&gt;', 'Pagina', 'Daniel'),
(24, 'Ley Dominga', 'ley-dominga', '2025-10-02', '1784049697_LEY-DOMINGA.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Ley Dominga Nº21.371&amp;nbsp;&lt;span&gt;Acompañamiento integral para personas en duelo gestacional y perinatal&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Se contempla una atención inicial por parte del equipo médico y psicosocial desde que ingresan a servicio de urgencias de maternidad para acompañar en la entrega de información o diagnósticos confirmado que no sean positivos para las personas que consultan.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Mediante esta ley el establecimiento tiene como objetivo otorgar acompañamiento a pacientes que estén viviendo pérdidas gestacionales, desde la contención, empatía y respeto por el duelo de cada madre y padre, prestando un servicio de calidad y respetuoso como lo señala el “Protocolo “Acompañamiento Integral para Personas en Duelo Gestacional y Perinatal\".&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Objetivo general:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Establecer los procedimientos y/o actividades que debe realizar el equipo de salud prestando atención y contención psico emocional a pacientes que se encuentran atravesando una pérdida gestacional o muerte perinatal, así como también para la persona significativa acompañante en el proceso, esto en base a lo contemplado en la ley 21.371.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Objetivos Específicos:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Asegurar medidas de acompañamiento para las pacientes que sufren pérdidas reproductivas en todo momento y lugar.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Fortalecer las acciones de seguimiento y derivación para la atención integral de las familias que viven duelo gestacional o perinatal.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Capacitar al equipo profesional del servicio en pro de garantizar el correcto cumplimiento del presente protocolo.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Medidas que establece la Ley N° 21.371:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Atención segura, privada, empática y compasiva.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Acompañamiento continuo.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Atención en espacios diferenciados.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Acciones de acuerdo a las necesidades de la familia, que favorezcan la despedida sensible.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Entrega de información oportuna.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Consenso para acompañamiento gineco-obstétrico y psicosocial.&amp;nbsp;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;-	Aspectos relacionados con licencia médica y/o permiso laboral.&lt;/p&gt;', 'Pagina', 'Daniel'),
(25, 'Chile Crece Contigo', 'chile-crece-contigo', '2025-10-02', '1784050284_CHILE-CRECE-CONTIGO.jpg.jpeg', '&lt;p style=\"text-align: justify;\"&gt;El Programa Chile Crece Contigo (ChCC) es una política pública integral del Estado de Chile, implementada desde el año 2007, que busca acompañar, proteger y apoyar a los niños, niñas y sus familias desde la gestación hasta los 9 años de edad, con énfasis en la primera infancia.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;En el ámbito hospitalario, ChCC cumple un rol fundamental en la promoción del desarrollo infantil temprano y el fortalecimiento del vínculo entre madre, padre, cuidadores y recién nacido. A través de la coordinación entre equipos de salud, se otorgan prestaciones universales y diferenciadas que incluyen:&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Acompañamiento desde el control prenatal, entregando orientación, información y apoyo a la gestante y su familia.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Entrega del Programa de Apoyo al Recién Nacido, que incluye implementos básicos como la cuna corral, vestimenta y artículos de estimulación temprana, promoviendo un entorno seguro y protector.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Apoyo en salud mental perinatal, mediante la detección oportuna de factores de riesgo y la derivación a programas de acompañamiento psicosocial.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Orientación en lactancia materna, cuidados del recién nacido y crianza respetuosa, favoreciendo prácticas que fortalecen el bienestar físico y emocional.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Derivación a redes de apoyo social y comunitarias, en caso de que las familias presenten mayores necesidades de acompañamiento.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;De esta manera, el programa busca reducir las brechas de desigualdad desde los primeros años de vida, fortaleciendo la equidad en salud y asegurando que cada niño y niña cuente con las condiciones necesarias para un desarrollo integral.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;&lt;br&gt;&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;b&gt;Acceso al Programa Chile Crece Contigo en el Hospital:&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Todo paciente beneficiario que se hospitaliza en el establecimiento de salud puede acceder a las prestaciones del Programa Chile Crece Contigo (ChCC), de manera gratuita y garantizada.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Esto incluye a:&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Gestantes, quienes reciben acompañamiento durante el proceso de embarazo y parto.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Puérperas, con apoyo en el período postparto y orientación en cuidados de la salud física y emocional.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Recién nacidos, beneficiarios de prestaciones universales como el set de apego seguro y controles de salud que favorecen el desarrollo integral.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;•	Niños, niñas y adolescentes hasta los 8 años de edad, quienes pueden acceder a acciones de acompañamiento, estimulación temprana, apoyo en salud mental y derivación a redes de apoyo cuando corresponda.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;El acceso es automático al momento de la hospitalización, sin necesidad de inscripción previa, ya que se activa mediante la atención clínica y el acompañamiento brindado por los equipos de salud.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;De esta manera, el hospital garantiza que cada madre, padre, cuidador y niño o niña reciba la orientación, apoyo y prestaciones necesarias, fortaleciendo el desarrollo integral y el bienestar familiar.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Mecanismos de Contacto y Horarios del Programa Chile Crece Contigo.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;El equipo del Programa Chile Crece Contigo del hospital se encuentra disponible para brindar orientación, acompañamiento y resolver consultas en horario hábil de lunes a viernes de 08:00 a 17:00 horas, y los días jueves de 08:00 a 16:00 horas.&lt;/p&gt;', 'Pagina', 'Daniel'),
(27, 'Escuela Hospitalaria', 'escuela-hospitalaria', '2025-10-02', '1784050299_ESCUELA-HOSPITALARIA.jpg.jpeg', '&lt;p style=\"text-align: justify; \"&gt;La Escuela Hospitalaria San José de Melipilla surge en el año 2020, cuando se detecta en la provincia de Melipilla la necesidad urgente de garantizar la continuidad escolar de niños, niñas y jóvenes que, a causa de distintas condiciones de salud, se ven impedidos de asistir a sus establecimientos de origen. Desde esa fecha comienza a gestarse el proyecto, impulsado por la Entidad Individual Educacional Alma y por la convicción profesional y personal de Jennifer Saldías Carreño, educadora diferencial, Magíster en Evaluación dinámica de propensión al Aprendizaje, Universidad Diego Portales y Máster en Pedagogía Hospitalaria a lo largo de la vida, Universidad de Barcelona, quien asumió el desafío de consolidar un espacio inclusivo y pertinente en el contexto hospitalario.&lt;/p&gt;&lt;p style=\"text-align: justify; \"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Tras un proceso de trabajo sostenido, en 2022 la escuela obtiene el reconocimiento oficial del Ministerio de Educación de Chile, consolidándose como una institución pionera en la provincia al ofrecer un servicio educativo especializado que asegura que la enfermedad no se convierta en una barrera para aprender ni para proyectar el futuro.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;La escuela se ha levantado con una misión clara: garantizar la continuidad del proceso educativo como un derecho esencial, asegurando que cada estudiante reciba una respuesta pedagógica flexible, inclusiva y centrada en su bienestar integral. La pedagogía hospitalaria es entendida aquí como un pilar de equidad y justicia social, que abre oportunidades educativas en contextos de adversidad y promueve la igualdad de condiciones para todos y todas.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;Desde sus inicios, la Escuela Hospitalaria San José de Melipilla ha fortalecido el vínculo entre estudiantes, familias y equipo de salud, conformando una red de apoyo que trasciende lo meramente académico para convertirse en un acompañamiento humano y cercano. Cada acción educativa se vive como un espacio de contención, esperanza y aprendizaje, favoreciendo tanto la recuperación como la reinserción escolar.&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"text-align: justify;\"&gt;A lo largo de su corta pero significativa trayectoria, la escuela se ha consolidado como un referente educativo y social en la comuna y la provincia, demostrando que es posible construir proyectos pedagógicos flexibles, pertinentes y de calidad, que responden a las necesidades individuales de cada estudiante. De este modo, reafirma que la educación hospitalaria es un derecho inalienable y una oportunidad vital para quienes enfrentan procesos de enfermedad, proyectándose como un espacio de vida, acompañamiento y aprendizaje que trasciende los límites del hospital.&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(28, 'Quiénes Somos', 'quienes-somos', '2026-02-03', '1784049721_QUIENES-SOMOS.jpg.jpeg', '&lt;p style=\"text-align: justify; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em;\"&gt;&lt;span&gt;En una sesión del 18 de Mayo de 1841, la Ilustre Municipalidad de Melipilla, con la asistencia del Gobernador José Ángel Ortúzar acordó la fundación de este hospital, con el propósito de dar asistencia a los enfermos carentes de recursos y que en aquel tiempo, fallecían sin socorro, a consecuencia de la viruela.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em;\"&gt;&lt;span&gt;La obra se inició con 800 y tantos pesos aportados por el Gobernador, fondos del Cabildo y la Comunidad. Sus inicios fueron difíciles, sin agua y falta de dinero. Recién en 1865 se establece una sala con 12 camas hasta 1870. En el período 1873 a 1878, el vecino D. Emeterio Goyenechea se hace cargo del establecimiento, dirigiéndolo personalmente y cubriendo los gastos de mantención por varios años.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em;\"&gt;&lt;span&gt;Durante esta administración en 1875, comienza una sesión para hombres y otra para mujeres, proyectándose la construcción de una farmacia, sala de operaciones y cocina. Bajo su administración el 8 de Julio de 1874, se instituyó el nombre de «San José » a nuestro hospital, cuyo título se mantiene en la actualidad. En 1878, por indicación del médico Don Alberto Delpiano nace la Sociedad de Señoras, denominada Instituto de la Caridad que se preocupó de las necesidades espirituales de los enfermos y económicas del Edificio.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1770126457_500060537_1056910333205596_2152743893101793267_n.jpg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1770126457_500060537_1056910333205596_2152743893101793267_n.jpg\" style=\"width: 100%; float: left;\" width=\"150\" class=\"note-float-left\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em; color: rgb(74, 71, 75); font-family: Lato, sans-serif;\"&gt;&lt;br&gt;&lt;/p&gt;&lt;p style=\"margin-right: 0px; margin-bottom: 1.5em; margin-left: 0px; border: 0px none; padding: 0px; line-height: 1.5em;\"&gt;&lt;b&gt;&lt;span&gt;Un nuevo hospital para la Provincia de Melipilla&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;El nuevo Hospital San José de Melipilla corresponde a una\r\ninversión de 99 mil millones de pesos que permitirán otorgarle cobertura de\r\nsalud a toda la provincia, compuesta por las comunas de Alhué, San Pedro, María\r\nPinto, Curacaví y Melipilla, beneficiando así a una población de más de 180.000\r\nhabitantes.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;El establecimiento está ubicado en el sector oriente de\r\nMelipilla, próximo al acceso por Ruta 78, frente a la Av. Vicuña Mackenna en un\r\nterreno de más de 4 hectáreas. Su superficie construida es superior a los\r\nsesenta mil metros cuadrados.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"margin-bottom: 12pt;\"&gt;&lt;/p&gt;&lt;div style=\"text-align: justify;\"&gt;&lt;span&gt;El nuevo hospital aumentará su dotación de camas de 137 a 239\r\ncamas de hospitalización. Incorporando una moderna UPC que considera 18\r\ncubículos de adultos y 12 para pediatría, sumando un total de 30 camas\r\ncríticas.&lt;/span&gt;&lt;/div&gt;&lt;span&gt;&lt;div style=\"text-align: justify;\"&gt;&lt;br&gt;&lt;/div&gt;&lt;/span&gt;&lt;span&gt;&lt;div style=\"text-align: justify; \"&gt;&lt;span&gt;Cuenta con 7 modernos y funcionales pabellones quirúrgicos, construidos\r\ncon la más alta tecnología en equipos y equipamiento medico, de acuerdo a las\r\nnecesidades sanitarias de la población. Además, tiene 12 camillas de cirugía\r\nmayor ambulatoria y 2 salas de parto integral.&lt;/span&gt;&lt;span&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: justify; \"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: justify; \"&gt;&lt;a href=\"/app/libs/artify/uploads/1770127813_WhatsApp Image 2025-03-18 at 11.25.03 (3).jpeg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;img src=\"/app/libs/artify/uploads/1770127813_WhatsApp Image 2025-03-18 at 11.25.03 (3).jpeg\" style=\"width: 1533px;\" width=\"150\"&gt;&lt;/a&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;&lt;/span&gt;&lt;p&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;El servicio de urgencias considera 3 box de adultos, 2 de pediatría, 1 ginecobstétrico, 2 camillas de reanimación y numerosas salas de procedimientos. Además, puestos de observación para pacientes adultos, pediátricos y de ginecobstetricia. Mientras que el edificio de consultas contempla amplias salas de espera y procedimientos, más de 58 box de atención, 4 salas de endoscopía, medicina física y rehabilitación, 12 sillones de diálisis, y una unidad de cuidados paliativos.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;El servicio de imagenología presenta un crecimiento sustancial, incorporando modernos equipos de la más alta tecnología,\r\nentre ellos un escáner de 64 cortes, dos equipos de rayos osteopulmonar, un\r\nmamógrafo, un ecógrafo y áreas para futuros crecimientos y nuevos equipos,\r\ncontribuyendo de esta forma a evitar el traslado y derivación de pacientes a\r\notros centros hospitalarios de la red.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;El nuevo recinto además cuenta con un helipuerto para\r\nfacilitar los traslados aéreos de los pacientes de mayor complejidad.&lt;/span&gt;&lt;/p&gt;&lt;p style=\"text-align: justify; margin-bottom: 12pt;\"&gt;&lt;a href=\"/app/libs/artify/uploads/1770127298_WhatsApp Image 2025-03-12 at 12.58.55.jpeg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;&lt;/a&gt;&lt;span&gt;El Hospital de Melipilla se encuentra actualmente ubicado completamente en sus nuevas dependencias y en completo funcionamiento, beneficiando a usuarias y usuarios de salud de las comunas de San Pedro, Alhué, María Pinto y Melipilla, sin duda un importante avance para la salud pública de la provincia.&lt;/span&gt;&lt;/p&gt;&lt;p class=\"MsoNormal\"&gt;&lt;/p&gt;', 'Pagina', 'Daniel');
INSERT INTO `pagina` (`id_pagina`, `titulo`, `slug`, `fecha`, `imagen`, `contenido`, `categoria`, `publicado_por`) VALUES
(32, 'Trabaja con Nosotros', 'trabaja-con-nosotros', '2026-07-28', '', '&lt;style&gt;\r\n@media (max-width:768px){\r\n\r\n    .responsive-table,\r\n    .responsive-table tbody,\r\n    .responsive-table tr,\r\n    .responsive-table td{\r\n        display:block;\r\n        width:100%;\r\n    }\r\n\r\n    .responsive-table tr{\r\n        margin-bottom:20px;\r\n        border:1px solid #ddd;\r\n    }\r\n\r\n    .responsive-table td{\r\n        border:none;\r\n        border-bottom:1px solid #eee;\r\n        text-align:center !important;\r\n        padding:15px;\r\n    }\r\n\r\n    .responsive-table img{\r\n        max-width:100%;\r\n        height:auto;\r\n    }\r\n\r\n    .responsive-table .fasc-button{\r\n        display:inline-block;\r\n        margin-top:10px;\r\n    }\r\n}\r\n&lt;/style&gt;\r\n&lt;table class=\"table table-bordered responsive-table\"&gt;\r\n    &lt;tbody&gt;\r\n        &lt;tr&gt;\r\n            &lt;td style=\"text-align:center; vertical-align:middle;\"&gt;\r\n    &lt;a href=\"/app/libs/artify/uploads/1785256601_5bd64e8289a5560e_CInternos-300x225.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;\r\n        &lt;img src=\"/app/libs/artify/uploads/1785256601_5bd64e8289a5560e_CInternos-300x225.png\" style=\"max-width:100%; height:auto;\" width=\"150\"&gt;\r\n    &lt;/a&gt;\r\n\r\n    &lt;div style=\"margin-top:10px;\"&gt;\r\n        &lt;a class=\"fasc-button fasc-size-large fasc-type-popout\" style=\"background-color:#f73946; color:#ffffff; padding: 5px;\" href=\"https://hospitaldemelipilla.cl/pagina/full/resultados-y-avances\"&gt;\r\n            Resultados y Avances\r\n        &lt;/a&gt;\r\n    &lt;/div&gt;\r\n&lt;/td&gt;\r\n            &lt;td style=\"text-align:center; vertical-align:middle;\"&gt;&lt;p&gt;\r\n                &lt;a href=\"/app/libs/artify/uploads/1785256610_ba0332aece5e7116_Post1-645x473.jpg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;\r\n                    &lt;img src=\"/app/libs/artify/uploads/1785256610_ba0332aece5e7116_Post1-645x473.jpg\" style=\"max-width:100%; height:auto;\" width=\"150\"&gt;&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;a href=\"/app/libs/artify/uploads/1785256610_ba0332aece5e7116_Post1-645x473.jpg\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;\r\n                &lt;/a&gt;\r\n&lt;a class=\"fasc-button fasc-size-large fasc-type-popout\" style=\"background-color: #33809e;color: #ffffff;height:fit-content; padding: 5px;\" href=\"https://hospitaldemelipilla.cl/pagina/full/postulaciones-disponibles/\"&gt;Postulaciones Disponibles&lt;/a&gt;\r\n            &lt;/p&gt;&lt;/td&gt;\r\n        &lt;/tr&gt;\r\n\r\n    \r\n        &lt;tr&gt;\r\n             &lt;td style=\"text-align:center; vertical-align:middle;\"&gt;\r\n               &lt;a href=\"/app/libs/artify/uploads/1785256620_81c8c48669829fb5_Postulacion-300x300.png\" data-fancybox=\"gallery\" data-caption=\"Foto\"&gt;\r\n                    &lt;img src=\"/app/libs/artify/uploads/1785256620_81c8c48669829fb5_Postulacion-300x300.png\" style=\"max-width:100%; height:auto;\" width=\"150\"&gt;\r\n                &lt;/a&gt;\r\n            &lt;/td&gt;\r\n&lt;td style=\"text-align:center; vertical-align:middle;\"&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Base de datos para Reemplazos&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Detalles de Postulación:&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Para ingresar sus antecedentes en Base de Datos de Profesionales &lt;a href=\"https://docs.google.com/forms/d/e/1FAIpQLScqmb5F9UQco1CuoreJDfVEM93O6LRZP3aiM05LVbh-X_KlOw/viewform\" target=\"_blank\"&gt;[ Pinche Aquí ]&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Para ingresar sus antecedentes en Base de Datos de Administrativos &lt;a href=\"https://docs.google.com/forms/d/e/1FAIpQLSeJS6LFXRj4pQ1YwsCcnC5lXKmXWGNVbVexalHMmJIjW7w6Xg/viewform\" target=\"_blank\"&gt;[ Pinche Aquí ]&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Para ingresar sus antecedentes en Base de Datos de Auxiliares &lt;a href=\"https://docs.google.com/forms/d/e/1FAIpQLScFgdxRvc4SnIpblgQbkPH_DpLfZjnsXxVOND3HskhjaQXkWA/viewform\" target=\"_blank\"&gt;[ Pinche Aquí ]&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Para ingresar sus antecedentes en Base de Datos de Técnicos &lt;a href=\"https://docs.google.com/forms/d/e/1FAIpQLSc_hHibp4jb5YFdwhWFPOwYr_fAiGKoqrGiOeyZFLXaEvaREA/viewform\" target=\"_blank\"&gt;[ Pinche Aquí ]&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Para ingresar sus antecedentes en Base de Datos de Profesionales Ley Médica &lt;a href=\"https://docs.google.com/forms/d/e/1FAIpQLSevmnJg6j-gI5gS3PafpzUUertOxkb3v6fTMldBTRPl0Hn5sQ/viewform\" target=\"_blank\"&gt;[ Pinche Aquí ]&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;/td&gt;\r\n        &lt;/tr&gt;\r\n    &lt;/tbody&gt;\r\n&lt;/table&gt;\r\n\r\n&lt;h4&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/h4&gt;&lt;h4&gt;&lt;strong&gt;Mas información: &amp;nbsp;&amp;nbsp; &amp;nbsp; &lt;a href=\"https://www.empleospublicos.cl/\"&gt;https://www.empleospublicos.cl/&lt;/a&gt;&lt;/strong&gt;&lt;/h4&gt;', 'Pagina', 'Daniel'),
(33, 'Resultados y Avances', 'resultados-y-avances', '2026-08-18', '', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td style=\"text-align: left; \"&gt;&lt;p&gt;Hospital san José de Melipilla informa resultado proceso de selección de &lt;b&gt;MÉDICO CIRUJANO CON ESPECIALIDAD EN CIRUGIA GENERAL PARA UNIDAD DE CIRUGIA&lt;/b&gt;&lt;br&gt;El proceso de Medico cirujano con especialidad en cirugía para unidad de cirugía se declara desierto.&lt;br&gt;motivo: Falta de postulantes idóneos&lt;br&gt;&lt;br&gt;atte.&lt;br&gt;Unidad reclutamiento y selección.&lt;/p&gt;&lt;p&gt;&lt;a href=\"https://drive.google.com/file/d/1pf91oiOBnp04agBCxRJOK0_NCuQGG9c8/view?usp=sharing\" target=\"_blank\"&gt;Resolución declara desierto proceso de selección&lt;/a&gt;&lt;/p&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td style=\"text-align: left; \"&gt;&lt;p&gt;Hospital san José de Melipilla informa resultado proceso de selección de &lt;b&gt;MÉDICO CIRUJANO CON ESPECIALIDAD EN CIRUGIA GENERAL PARA UNIDAD DE URGENCIA&lt;/b&gt;&lt;br&gt;Se aprueban las bases del proceso de Medico cirujano con especialidad en cirugía general para unidad de emergencia&lt;br&gt;Una vez finalizado el proceso de Reclutamiento y selección interno, este se adjudica a:&lt;br&gt;&lt;br&gt;&lt;b&gt;BUGUEIRO BERTIER&lt;/b&gt;&lt;br&gt;&lt;br&gt;atte.&lt;br&gt;Unidad reclutamiento y selección.&lt;/p&gt;&lt;p&gt;&lt;a href=\"https://drive.google.com/file/d/1FawlGsglpw7bpJ3vBuMNQVedD4mRFG8Z/view?usp=drive_link\" target=\"_blank\"&gt;Resolución declara finalizado proceso de selección&lt;/a&gt;&lt;/p&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td style=\"text-align: left; \"&gt;&lt;p&gt;Hospital san José de Melipilla informa resultado proceso de selección de &lt;b&gt;ANALISTA DE PERSONAL EN GESTION DE HORA EXTRA UNIDAD GESTION Y ADMINISTRACION DE PERSONAS&lt;/b&gt;&lt;br&gt;Se aprueban las bases del proceso de Analista de personal en gestión de hora extra unidad gestión y administración de personas.&lt;br&gt;Una vez finalizado el proceso de Reclutamiento y selección interno, este se adjudica a:&lt;br&gt;&lt;br&gt;&lt;b&gt;GONZALEZ OLIVARES&lt;/b&gt;&lt;br&gt;&lt;br&gt;atte.&lt;br&gt;Unidad reclutamiento y selección.&lt;/p&gt;&lt;p&gt;&lt;a href=\"https://drive.google.com/file/d/1h0F17dScvUzIwMdjq8CJZATcIlICkRRO/view?usp=sharing\" target=\"_blank\"&gt;Resolución declara finalizado proceso de selección&lt;/a&gt;&lt;/p&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;br&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Hospital san José de Melipilla informa resultado proceso de selección de &lt;b&gt;TECNICO EN ALIMENTACION DE UNIDAD DE NUTRICION Y SEDILE-CEFE&lt;/b&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Una vez finalizado el proceso de Reclutamiento y selección interno, este se adjudica a:&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;br&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;&lt;b&gt;SANTIBAÑEZ ALVAREZ&lt;/b&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;br&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;atte.&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Unidad reclutamiento y selección.&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;&lt;a href=\"https://drive.google.com/file/d/1tY4c4IFyp18EH_Sbc1rvwYoSL4Fi1mjF/view?usp=sharing\" target=\"_blank\"&gt;Resolución Declara por finalizado proceso de selección&amp;nbsp;&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td style=\"text-align: left; \"&gt;&lt;br&gt;Hospital san José de Melipilla informa resultado proceso de selección de&lt;b&gt; ENFERMERO(A) SUPERVISOR(A) BLOQUE MÉDICO QUIRURGICO MEDICINA B&amp;nbsp;&lt;/b&gt;&lt;br&gt;Una vez finalizado el proceso de Reclutamiento y selección abierto, este se adjudica a:&lt;br&gt;&lt;br&gt;&lt;b&gt;LUCERO BUSTOS&lt;/b&gt;&lt;br&gt;&lt;br&gt;atte.&lt;br&gt;Unidad reclutamiento y selección.&lt;br&gt;&lt;a href=\"https://drive.google.com/file/d/1US2gxlIHIMeY1F9vu6f-hn07gnjWzS_J/view?usp=sharing\" target=\"_blank\"&gt;Resolución Declara por finalizado proceso de selección&amp;nbsp;&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\" style=\"text-align: justify;\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;&lt;p&gt;&lt;/p&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Hospital San José de Melipilla informa avances en el Proceso de Reclutamiento y Selección&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Se informa a todos(as) los(as) postulantes del proceso de selección para el cargo de &lt;b&gt;\"PSICÓLOGA(O) PROGRAMA CUIDADOS PALIATIVOS\"&amp;nbsp;&lt;/b&gt;&lt;/span&gt;&lt;span&gt;que, una vez finalizada la etapa de Análisis Curricular, se ha determinado que los(as) siguientes candidatos(as) han sido seleccionados(as) para continuar con la siguiente fase del proceso.&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;&lt;b&gt;APELLIDOS POSTULANTES&lt;/b&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;PEÑAILILLO ALFONSO&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;ROMERO STUARDO&amp;nbsp;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;HENRIETTA MORENO&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;SARMIENTO CARREÑO&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;MARTÍNEZ VÁSQUEZ&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;CHACÓN CONTRERAS&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;MARTÍNEZ MUÑOZ&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;MARTÍN MEZA&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;MATAMALA YÁÑEZ&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;SÁEZ ZÁRATE&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: center;\"&gt;&lt;span&gt;MENESES VILLAROEL&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;Si Ud. NO figura en la nómina precedente, agradecemos su interés en trabajar con nosotros y le invitamos a que siga visitando nuestra página web en donde continuamente estaremos informando de próximos.&lt;/span&gt;&lt;/div&gt;&lt;div style=\"text-align: left;\"&gt;&lt;span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;&lt;br&gt;&lt;p&gt;&lt;/p&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;', 'Pagina', 'Daniel'),
(34, 'Postulaciones Disponibles', 'postulaciones-disponibles', '2026-08-19', '', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;Tipo de concurso&lt;/td&gt;&lt;td&gt;Plataforma&lt;/td&gt;&lt;td&gt;Cargo&lt;/td&gt;&lt;td&gt;Vacantes&lt;/td&gt;&lt;td&gt;Fecha&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Practica Profesional&lt;/td&gt;&lt;td&gt;&lt;p&gt;&lt;a href=\"https://practicas2.serviciocivil.cl/concursos-spl/opencms/convocatorias/OP-30409\" target=\"_blank\"&gt;https://practicas2.serviciocivil.cl&lt;/a&gt;&lt;br&gt;&lt;/p&gt;&lt;/td&gt;&lt;td&gt;Práctica de Educación Superior Técnico Profesional para Unidad Sistemas Eléctricos - Ciencias - Presencial&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;desde 31/08/2026 hasta 04/09/2026 a las 23:59 hrs&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;a href=\"https://practicas2.serviciocivil.cl/concursos-spl/opencms/convocatorias/OP-30409\" target=\"_blank\"&gt;Práctica de Educación Superior Técnico Profesional para Unidad Sistemas Eléctricos - Ciencias - Presencial&lt;/a&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;&lt;table class=\"table table-bordered\"&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;Tipo de Concurso&lt;/td&gt;&lt;td&gt;Plataforma&lt;/td&gt;&lt;td&gt;Cargo&lt;/td&gt;&lt;td&gt;Vacantes&lt;/td&gt;&lt;td&gt;Fecha&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Practica Profesional&lt;/td&gt;&lt;td&gt;&lt;p&gt;&lt;a href=\"https://practicas2.serviciocivil.cl/concursos-spl/opencms/convocatorias/OP-30407\" target=\"_blank\"&gt;https://practicas2.serviciocivil.cl&lt;/a&gt;&lt;br&gt;&lt;/p&gt;&lt;/td&gt;&lt;td&gt;Práctica de Educación Superior Profesional para Unidad Sistemas Eléctricos - Ciencias - Presencial&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;desde 31/08/2026 hasta 04/09/2026 a las 23:59 hrs&lt;/td&gt;&lt;/tr&gt;&lt